raw = ['1250', '980.5', '', 'NA', '1100', 'abc']
values, missing = [], 0
for item in raw:
    try:
        values.append(float(item))
    except ValueError:
        missing += 1

print(values)                  # [1250.0, 980.5, 1100.0]
print(missing)                 # 3
print(round(sum(values) / len(values), 2))  # 1110.17

def age_band(age, edges=(0, 18, 35, 60, 100)):
    """Return the (low, high] band label for age, or None if outside."""
    for low, high in zip(edges, edges[1:]):
        if low < age <= high:
            return f'({low}, {high}]'
    return None

ages = [16, 18, 22, 47, 70]
print([age_band(a) for a in ages])
# ['(0, 18]', '(0, 18]', '(18, 35]', '(35, 60]', '(60, 100]']

